# %% pts/mod/_models.pct.py 6
def _validate_single_path_component(value: str, label: str) -> None:
    """
    Raise `ValueError` unless `value` can be used verbatim as one directory name.

    This is the shared, safety-critical half of `validate_box_name` and
    `validate_box_index_name`: a value that is not a single path component
    spreads whatever it names across a nested tree, or (with `..`) escapes the
    directory it was meant to stay inside.
    """
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string.")
    if value in (".", ".."):
        raise ValueError(f"{label} must not be {value!r}.")
    for forbidden in ("/", "\\", "\0"):
        if forbidden in value:
            raise ValueError(
                f"{label} must be a single path component, but {value!r} contains "
                f"{forbidden!r}. Names are used verbatim as directory names."
            )
    if Path(value).name != value:
        raise ValueError(f"{label} must be a single path component: {value!r}")

# %% pts/mod/_models.pct.py 7
def validate_box_name(name: str) -> None:
    """
    Raise `ValueError` if `name` cannot be used as a box name.

    A box's `index_name` (`{box_id}__{name}`) is interpolated straight into
    filesystem paths, so a name that is not a single path component would
    spread the box over a nested directory tree — and the top level of that
    tree does not parse as a box registration, which breaks every subsequent
    `create_boxyard_meta` for the whole yard.

    This is the policy for *new* box names, so it is stricter than
    `validate_box_index_name`: on top of the path-component rule it also
    forbids surrounding whitespace and a leading '.'.
    """
    _validate_single_path_component(name, "Box name")
    if name != name.strip():
        raise ValueError(
            f"Box name must not have leading or trailing whitespace: {name!r}"
        )
    if name.startswith("."):
        raise ValueError(f"Box name must not start with a '.': {name!r}")

# %% pts/mod/_models.pct.py 8
def validate_box_index_name(index_name: str) -> None:
    """
    Raise `ValueError` if `index_name` cannot be used as one directory name.

    An `index_name` (`{box_id}__{name}`) is interpolated straight into paths —
    the per-box lock directory `<data>/locks/boxes/{index_name}/` among them —
    so one containing a separator would nest the lock inside a tree, and one
    containing `..` would place it outside the locks directory altogether.

    Deliberately weaker than `validate_box_name`: it enforces only the
    path-component rule, not the cosmetic policy (no leading '.', no
    surrounding whitespace) that applies when *creating* a box. Box names went
    unvalidated before v0.3.3, so a long-lived yard may hold boxes whose names
    would fail today's policy — those boxes must still be lockable.
    """
    _validate_single_path_component(index_name, "Box index name")

# %% pts/mod/_models.pct.py 9
def _create_box_subid(character_set: str, length: int) -> str:
    return "".join(random.choices(character_set, k=length))

# %% pts/mod/_models.pct.py 10
def format_creation_timestamp(
    config: boxyard.config.Config, dt: datetime
) -> str:
    """
    Render `dt` in the timestamp format this yard's box ids use.

    Extracted so that the format switch lives in exactly one place. It used to
    be written out twice -- here and in `new_box`, for the
    `creation_timestamp_utc` override -- and a box id whose timestamp half was
    formatted by a *different* copy of this switch is precisely the kind of
    drift that produces ids the rest of the yard cannot parse.
    """
    from .config import BoxTimestampFormat

    if config.box_timestamp_format == BoxTimestampFormat.DATE_AND_TIME:
        return dt.strftime(const.BOX_TIMESTAMP_FORMAT)
    elif config.box_timestamp_format == BoxTimestampFormat.DATE_ONLY:
        return dt.strftime(const.BOX_TIMESTAMP_FORMAT_DATE_ONLY)
    else:
        raise Exception(
            f"Invalid box timestamp format: {config.box_timestamp_format}"
        )

# %% pts/mod/_models.pct.py 11
def generate_unique_box_id(
    config: boxyard.config.Config,
    existing_ids: set[str],
    max_attempts: int = 100,
    creation_timestamp: str | None = None,
) -> tuple[str, str]:
    """
    Generate a box ID that doesn't collide with existing IDs.

    Args:
        config: Boxyard config (for timestamp format and subid settings)
        existing_ids: Set of existing box IDs to check against
        max_attempts: Maximum generation attempts before raising error
        creation_timestamp: Use this already-formatted timestamp instead of
            "now". The caller that passes it (`new_box`, for
            `--creation-timestamp-utc`) needs the collision check to run
            against the id it will ACTUALLY use: it used to let this function
            pick a timestamp, check `<generated_ts>_<subid>` for collisions,
            and then substitute its own timestamp afterwards -- so the id that
            got written was never the id that was checked.

    Returns:
        Tuple of (creation_timestamp, box_subid)

    Raises:
        RuntimeError: If unable to generate unique ID after max_attempts
    """
    for _ in range(max_attempts):
        if creation_timestamp is None:
            timestamp = format_creation_timestamp(config, datetime.now(timezone.utc))
        else:
            timestamp = creation_timestamp

        box_subid = _create_box_subid(
            config.box_subid_character_set, config.box_subid_length
        )
        box_id = f"{timestamp}_{box_subid}"

        if box_id not in existing_ids:
            return timestamp, box_subid

    raise RuntimeError(
        f"Failed to generate unique box ID after {max_attempts} attempts. "
        f"This should be extremely rare - please report this issue."
    )

