def create_user_box_group_symlinks(
    config: boxyard.config.Config,
):
    from collections import defaultdict
    from .config import BoxGroupTitleMode, VirtualBoxGroupConfig

    box_metas = [
        box_meta
        for box_meta in get_boxyard_meta(config).box_metas
        if box_meta.check_included(config)
    ]
    box_metas.sort(key=lambda x: x.creation_timestamp_datetime)
    groups, virtual_box_groups = get_box_group_configs(config, box_metas)
    symlink_paths = []

    for vg in virtual_box_groups:
        if vg in groups:
            print(f"Warning: Virtual box group '{vg}' is also a regular box group.")
    groups.update(virtual_box_groups)

    def _get_symlink_title(box_meta: BoxMeta, group_config: BoxGroupConfig) -> str:
        if group_config.box_title_mode == BoxGroupTitleMode.INDEX_NAME:
            title = box_meta.index_name
        elif group_config.box_title_mode == BoxGroupTitleMode.DATETIME_AND_NAME:
            title = f"{box_meta.creation_timestamp_utc}__{box_meta.name}"
        elif group_config.box_title_mode == BoxGroupTitleMode.NAME:
            title = box_meta.name
        else:
            raise Exception(f"Invalid box title mode: {group_config.box_title_mode}")
        return title

    # Generate all symlink paths to create
    _symlinks = []
    for group_name, group_config in groups.items():
        title_counter = defaultdict(int)
        group_symlink_name = group_config.symlink_name or group_name
        for box_meta in box_metas:
            if not box_meta.check_included(config):
                continue
            if isinstance(group_config, VirtualBoxGroupConfig):
                if not group_config.is_in_group(box_meta.groups):
                    continue
            else:
                if group_name not in box_meta.groups:
                    continue
            dest_path = box_meta.get_local_part_path(config, BoxPart.DATA)
            # Disambiguate boxes that would take the same title in this group.
            #
            # This had two compounding bugs. The threshold was `> 1`, but the
            # counter holds how many boxes have ALREADY taken the title, so the
            # second box to want "foo" saw 1, failed the test, and took "foo"
            # as well. And the increment landed on the REWRITTEN key, so once a
            # box became "foo (CONFLICT 2)" the count for "foo" stopped rising
            # and every later box computed that same suffix.
            #
            # The result was that N boxes sharing a title produced only TWO
            # distinct names, and the symlink creation below resolved each
            # collision last-one-wins -- silently dropping the other boxes from
            # the group. With `box_title_mode = "name"`, which every `active/*`
            # group uses, that meant real work quietly missing from ~/g.
            base_title = _get_symlink_title(box_meta, group_config)
            seen = title_counter[base_title]
            title = base_title if seen == 0 else f"{base_title} (CONFLICT {seen})"
            title_counter[base_title] += 1
            symlink_path = config.user_box_groups_path / group_symlink_name / title
            _symlinks.append((dest_path, symlink_path))

    # Remove all existing symlinks that are not in the _symlinks list
    _symlink_paths = [symlink_path for _, symlink_path in _symlinks]
    for path in config.user_box_groups_path.glob("**/*"):
        if path in _symlink_paths:
            continue
        if path.is_symlink():
            path.unlink()

    # Now check for any remaining debris
    def _inspect_folder(path: Path) -> None:
        if path.is_symlink():
            return
        for p in path.iterdir():
            if p.name.startswith("."):
                continue
            if p.is_dir():
                _inspect_folder(p)
            else:
                if p not in _symlink_paths:
                    raise Exception(
                        f"File '{p}' is in the user box group path '{config.user_box_groups_path}'."
                    )

    for path in config.user_box_groups_path.glob("*"):
        if path.name.startswith("."):
            continue
        if path.is_dir():
            _inspect_folder(path)
        else:
            raise Exception(
                f"'{path}' is in the user box group path '{config.user_box_groups_path}' but is not a directory!"
            )

    # Create the symlinks
    for dest_path, symlink_path in _symlinks:
        symlink_path.parent.mkdir(parents=True, exist_ok=True)
        if (
            symlink_path.exists() or symlink_path.is_symlink()
        ):  # is_symlink() catches broken symlinks
            if symlink_path.is_symlink():
                if symlink_path.resolve() != dest_path.resolve():
                    symlink_path.unlink()
                else:
                    continue  # The symlink already points to the correct destination so leave it as it is
            else:
                raise Exception(
                    f"'{symlink_path}' is in the user box group path '{config.user_box_groups_path}' but is not a symlink!"
                )
        symlink_path.symlink_to(dest_path, target_is_directory=True)

    # Remove every empty directory, deepest first.
    #
    # This used to carry an `is_group_folder` guard that exempted directories
    # whose path matched a GROUP NAME. It was accidental, not a policy: a
    # group's directory is named after `symlink_name` when it has one, and
    # those are nested paths (`all/proj`, `active/all`), so the guard never
    # matched on a config that sets them -- every group in this fleet's config
    # does -- and matched on every group in a config that does not. The same
    # code pruned empty group directories or kept them depending on a field
    # that has nothing to do with pruning.
    #
    # Pruning is the behaviour worth keeping, so it is now the behaviour the
    # code states. A group that has emptied out is not information: `~/g` is a
    # navigation surface, it is rebuilt from scratch on every run, and the
    # directory reappears the moment a box joins the group again.
    #
    # Note what this does NOT decide. A directory is only ever created as the
    # parent of a symlink, so a group that has never had a box on this machine
    # has no directory either way -- mymain has 28 of the 38 groups' directories
    # and none of them are empty. The pruning only governs a group whose LAST
    # box goes away.
    def _remove_empty_folders(path: Path) -> None:
        if path.is_symlink() or not path.is_dir():
            return
        for p in path.iterdir():
            if p.name.startswith("."):
                continue
            if p.is_dir():
                _remove_empty_folders(p)
        if len([p for p in path.iterdir() if not p.name.startswith(".")]) == 0:
            path.rmdir()

    for path in config.user_box_groups_path.glob("*"):
        if path.name.startswith("."):
            continue
        _remove_empty_folders(path)

