def record_meta_base(
    config: "boxyard.config.Config", box_meta: "BoxMeta", verbose: bool = False
) -> None:
    """
    Snapshot the boxmeta that local and remote have just agreed on.

    Call this ONLY where the two sides are known to match: the META sync
    reported SYNCED, or a transfer completed and was verified. Anywhere else
    would record a base that never was.

    A STALE base is worse than no base at all. A merge computes what each side
    changed by diffing against it, so a base that does not correspond to a real
    shared state produces a confidently wrong answer, where a missing one makes
    the merge decline and fall back to today's refusal. So this writes through
    a temporary file and renames it into place -- and on any failure REMOVES
    the base rather than leaving whatever was there before.
    """
    import os
    import shutil
    import tempfile

    source = box_meta.get_local_part_path(config, BoxPart.META)
    dest = box_meta.get_local_meta_base_path(config)
    if not source.is_file():
        # No local boxmeta means there is no agreed state to record. Drop any
        # base rather than keep one that no longer describes anything.
        dest.unlink(missing_ok=True)
        return

    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp_fd, tmp_name = tempfile.mkstemp(dir=dest.parent, prefix=".meta.base.", suffix=".tmp")
    os.close(tmp_fd)
    tmp_path = Path(tmp_name)
    try:
        shutil.copyfile(source, tmp_path)
        os.replace(tmp_path, dest)
    except Exception:
        tmp_path.unlink(missing_ok=True)
        dest.unlink(missing_ok=True)
        raise
    if verbose:
        print(f"Recorded the META merge base for {box_meta.index_name}.")


def read_meta_base(
    config: "boxyard.config.Config", box_meta: "BoxMeta"
) -> "BoxMeta | None":
    """
    The recorded base, or None when there is not one to trust.

    None is a legitimate, expected state -- a box that has not synced since
    this was introduced simply has no base -- so it is returned rather than
    raised. A base that exists but does not PARSE is a different matter: that
    is corruption, and merging against a half-read file would be worse than
    declining, so it is removed and None returned.
    """
    import tomllib as _tomllib

    path = box_meta.get_local_meta_base_path(config)
    if not path.is_file():
        return None
    try:
        return BoxMeta.load_from_path(
            path,
            creation_timestamp_utc=box_meta.creation_timestamp_utc,
            box_subid=box_meta.box_subid,
            name=box_meta.name,
            storage_location=box_meta.storage_location,
        )
    except (_tomllib.TOMLDecodeError, ValueError):
        # Unparseable, or valid TOML that is not a boxmeta (pydantic's
        # ValidationError is a ValueError). Either way there is nothing here to
        # diff against, so drop it and let the caller decline.
        #
        # Deliberately NOT a bare `except`: an OSError reading a file that
        # `is_file()` just said exists is a real problem with the data
        # directory, and quietly deleting the base on the way past would hide
        # it.
        path.unlink(missing_ok=True)
        return None

